import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Packaging & Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/packaging.md","filePath":"dev-guide/packaging.md","lastUpdated":1785993908000}'),n={name:"dev-guide/packaging.md"};function o(l,e,d,r,p,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="packaging-deployment" tabindex="-1">Packaging &amp; Deployment <a class="header-anchor" href="#packaging-deployment" aria-label="Permalink to &quot;Packaging &amp; Deployment&quot;">​</a></h1><h2 id="how-plugins-are-discovered" tabindex="-1">How plugins are discovered <a class="header-anchor" href="#how-plugins-are-discovered" aria-label="Permalink to &quot;How plugins are discovered&quot;">​</a></h2><p>The App loads every <code>.dll</code> it finds in its own <code>Plugins/</code> folder (next to <code>Lertaro.App.exe</code>) at startup, looking for types implementing <code>IPlugin</code>. There&#39;s no separate manifest file — the assembly itself, plus whichever SDK interfaces its types implement, is the full contract.</p><h2 id="shipping-your-own-dependencies" tabindex="-1">Shipping your own dependencies <a class="header-anchor" href="#shipping-your-own-dependencies" aria-label="Permalink to &quot;Shipping your own dependencies&quot;">​</a></h2><p>If your plugin needs managed or native dependency DLLs of its own (a database driver, a native interop library, ...), put them in their own subdirectory under the App&#39;s <code>Plugins/</code> folder — e.g. <code>Plugins/YourPlugin/YourPlugin.dll</code> plus its dependencies right alongside it — instead of flat in <code>Plugins/</code> itself. The loader scans <code>Plugins/</code> recursively, and <code>Assembly.LoadFrom</code>&#39;s own same-directory dependency probing then resolves your dependencies automatically, without spilling them into every other plugin&#39;s load directory.</p><p>A non-.NET file the scanner encounters along the way (a native DLL like <code>e_sqlite3.dll</code>) is expected and logged at <code>Debug</code>, not <code>Error</code> — only a real managed assembly that genuinely fails to load logs at <code>Error</code>.</p><p>See the <code>BrowserData</code> plugin&#39;s <code>.csproj</code> for a complete, real example: it bundles <code>Microsoft.Data.Sqlite</code> and its native <code>SQLitePCLRaw</code>/<code>e_sqlite3.dll</code> dependencies this way, with post-build/post-publish targets that nest them into its own subfolder regardless of which build mechanism produced them.</p><h2 id="automating-the-copy-during-development" tabindex="-1">Automating the copy during development <a class="header-anchor" href="#automating-the-copy-during-development" aria-label="Permalink to &quot;Automating the copy during development&quot;">​</a></h2><p>The plugins shipped with Lertaro itself (<code>CoreExtensions</code>, <code>PinyinAlias</code>) automate deployment with a post-build target in their <code>.csproj</code>, copying the freshly-built DLL straight into the App&#39;s own output <code>Plugins/</code> folder so a rebuild is immediately picked up on the next launch:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Adapt the destination path to wherever your own build output and the Lertaro App installation actually live.</p><h2 id="embedded-translations" tabindex="-1">Embedded translations <a class="header-anchor" href="#embedded-translations" aria-label="Permalink to &quot;Embedded translations&quot;">​</a></h2><p>If your plugin implements <code>ITranslationProvider</code> (see <a href="./sdk/ui-extensions.html">UI &amp; Preview Extensions</a>), ship its translation JSON files as embedded resources rather than loose files, so they travel with the DLL:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>TranslationService.LoadEmbeddedTranslations</code> (see <a href="./sdk/services.html">Host Services</a>) reads them back out of the assembly at runtime by culture name.</p><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>Give your plugin&#39;s <code>.csproj</code> a <code>&lt;Version&gt;</code>; it&#39;s shown to users on its card under <strong>Settings → Plugins</strong>, alongside the <code>PluginSdk</code> version your plugin was built against — useful for confirming compatibility when the SDK surface changes.</p>`,17)])])}const k=i(n,[["render",o]]);export{g as __pageData,k as default};
